program.source:
Function word <- HowItWent(code As Integer)
  Define word As String;
  If code = 200 Then
    word <- "fine";
  Else
    word <- "problem";
  EndIf
EndFunction

Algorithm StatusCheck
  Define code As Integer;
  Read code;
  Write HowItWent(code);
EndAlgorithm

